import "forge-std/Test.sol";
import "../src/1-sgrok_1.sol";

contract RemoveLimitsTest is Test {
    SpaceGrok public token;
    address public owner = address(0x1);
    address public attacker = address(0x2);

    function setUp() public {
        vm.startPrank(owner);
        token = new SpaceGrok();
        vm.stopPrank();
